package api

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"sync"
	"testing"
)

const conditionalConfigPath = "/api/v1/environments/prod/flags/checkout/config/conditional"

func (h *apiHarness) conditional(t *testing.T, payload string) *httptest.ResponseRecorder {
	t.Helper()
	return h.do(t, http.MethodPost, conditionalConfigPath, payload)
}

func errorCode(rec *httptest.ResponseRecorder) string {
	var out struct {
		Error struct {
			Code    string `json:"code"`
			Message string `json:"message"`
		} `json:"error"`
	}
	if err := json.Unmarshal(rec.Body.Bytes(), &out); err != nil {
		return ""
	}
	return out.Error.Code
}

func newVersion(rec *httptest.ResponseRecorder) string {
	var out struct {
		Version string `json:"version"`
	}
	if err := json.Unmarshal(rec.Body.Bytes(), &out); err != nil {
		return ""
	}
	return out.Version
}

func TestConditionalConfigCreatesWhenNoLiveVersion(t *testing.T) {
	h := newHarness(t)
	h.createEnv(t, "prod")
	h.createFlag(t, "checkout")
	h.setTime("2026-01-01T02:00:00Z")

	rec := h.conditional(t, `{"expected_version":null,"enabled":true,"percentage":25}`)
	if rec.Code != http.StatusCreated {
		t.Fatalf("status = %d body = %s, want 201", rec.Code, rec.Body.String())
	}
	var out map[string]any
	if err := json.Unmarshal(rec.Body.Bytes(), &out); err != nil {
		t.Fatalf("decode: %v", err)
	}
	if out["flag_key"] != "checkout" || out["environment"] != "prod" {
		t.Errorf("identity = %v/%v", out["flag_key"], out["environment"])
	}
	if out["enabled"] != true || out["percentage"] != float64(25) {
		t.Errorf("payload fields = enabled %v percentage %v", out["enabled"], out["percentage"])
	}
	if out["tombstone"] != false {
		t.Errorf("tombstone = %v, want false", out["tombstone"])
	}
	window, ok := out["window"].(map[string]any)
	if !ok || window["starts_at"] != nil || window["ends_at"] != nil {
		t.Errorf("window = %v, want null endpoints", out["window"])
	}
	if version, _ := out["version"].(string); version == "" {
		t.Errorf("version missing: %v", out)
	}
	if out["changed_at"] != "2026-01-01T02:00:00Z" {
		t.Errorf("changed_at = %v", out["changed_at"])
	}
}

func TestConditionalConfigUpdatesOnlyWhenVersionCurrent(t *testing.T) {
	h := newHarness(t)
	h.createEnv(t, "prod")
	h.createFlag(t, "checkout")
	h.setTime("2026-01-01T02:00:00Z")

	v1 := newVersion(h.conditional(t, `{"expected_version":null,"enabled":true,"percentage":10}`))
	if v1 == "" {
		t.Fatal("first create failed")
	}

	// Stale expectation: something already exists, null no longer matches.
	if rec := h.conditional(t, `{"expected_version":null,"enabled":true,"percentage":20}`); rec.Code != http.StatusConflict || errorCode(rec) != "VersionConflict" {
		t.Fatalf("null after create = %d %s, want 409 VersionConflict", rec.Code, rec.Body.String())
	}
	// Wrong explicit version.
	if rec := h.conditional(t, `{"expected_version":"cfg-does-not-exist","enabled":true,"percentage":20}`); rec.Code != http.StatusConflict || errorCode(rec) != "VersionConflict" {
		t.Fatalf("bogus version = %d %s, want 409 VersionConflict", rec.Code, rec.Body.String())
	}

	h.setTime("2026-01-01T03:00:00Z")
	rec := h.conditional(t, `{"expected_version":"`+v1+`","enabled":false,"percentage":0}`)
	if rec.Code != http.StatusCreated {
		t.Fatalf("matching version = %d %s, want 201", rec.Code, rec.Body.String())
	}
	v2 := newVersion(rec)
	if v2 == v1 {
		t.Fatalf("new version = %s, want a distinct version", v2)
	}

	// The old version cannot be replayed.
	if rec := h.conditional(t, `{"expected_version":"`+v1+`","enabled":true,"percentage":50}`); rec.Code != http.StatusConflict {
		t.Fatalf("stale replay = %d, want 409", rec.Code)
	}
	// Only the latest version drives current state.
	evaluated := h.must(t, http.MethodGet, "/api/v1/environments/prod/evaluate?marker=alpha", "")
	flags := evaluated["flags"].([]any)
	checkout := flags[0].(map[string]any)
	if checkout["status"] != "off" {
		t.Fatalf("current status = %v, want off from enabled=false", checkout["status"])
	}
}

func TestConditionalConfigNullExpectationAfterTombstoneSucceeds(t *testing.T) {
	h := seededHarness(t)
	// seededHarness leaves checkout tombstoned (v3) at 2026-01-02T00:00:00Z.
	h.setTime("2026-01-02T01:00:00Z")
	rec := h.conditional(t, `{"expected_version":null,"enabled":true,"percentage":42}`)
	if rec.Code != http.StatusCreated {
		t.Fatalf("null after tombstone = %d %s, want 201", rec.Code, rec.Body.String())
	}

	// Tombstone version is not valid as expected_version: current is v4 now,
	// and even before this write the tombstone version must not match.
	if rec := h.conditional(t, `{"expected_version":"`+h.v3["version"].(string)+`","enabled":true,"percentage":1}`); rec.Code != http.StatusConflict {
		t.Fatalf("tombstone version as expectation = %d, want 409", rec.Code)
	}
}

func TestConditionalConfigConcurrentSameVersionHasOneWinner(t *testing.T) {
	h := newHarness(t)
	h.createEnv(t, "prod")
	h.createFlag(t, "checkout")
	h.setTime("2026-01-01T02:00:00Z")
	v1 := newVersion(h.conditional(t, `{"expected_version":null,"enabled":true,"percentage":10}`))

	const n = 16
	payload := `{"expected_version":"` + v1 + `","enabled":true,"percentage":99}`
	start := make(chan struct{})
	var wg sync.WaitGroup
	results := make([]int, n)
	wg.Add(n)
	for i := 0; i < n; i++ {
		go func(i int) {
			defer wg.Done()
			<-start
			req := httptest.NewRequest(http.MethodPost, conditionalConfigPath, strings.NewReader(payload))
			req.Header.Set("Content-Type", "application/json")
			rec := httptest.NewRecorder()
			h.router.ServeHTTP(rec, req)
			results[i] = rec.Code
		}(i)
	}
	close(start)
	wg.Wait()

	created, conflicts := 0, 0
	for _, code := range results {
		switch code {
		case http.StatusCreated:
			created++
		case http.StatusConflict:
			conflicts++
		default:
			t.Fatalf("unexpected status %d", code)
		}
	}
	if created != 1 || conflicts != n-1 {
		t.Fatalf("created = %d conflicts = %d, want exactly 1 / %d", created, conflicts, n-1)
	}

	history := h.must(t, http.MethodGet, "/api/v1/environments/prod/flags/checkout/history", "")
	versions := history["versions"].([]any)
	if len(versions) != 2 {
		t.Fatalf("history length = %d, want only the original and one winning append", len(versions))
	}
}

func TestConditionalConfigValidatesRequestBody(t *testing.T) {
	h := newHarness(t)
	h.createEnv(t, "prod")
	h.createFlag(t, "checkout")

	cases := []struct {
		name    string
		payload string
		code    string
	}{
		{"missing expected_version", `{"enabled":true,"percentage":10}`, "InvalidRequest"},
		{"numeric expected_version", `{"expected_version":7,"enabled":true,"percentage":10}`, "InvalidRequest"},
		{"boolean expected_version", `{"expected_version":true,"enabled":true,"percentage":10}`, "InvalidRequest"},
		{"missing enabled", `{"expected_version":null,"percentage":10}`, "InvalidRequest"},
		{"null enabled", `{"expected_version":null,"enabled":null,"percentage":10}`, "InvalidRequest"},
		{"string enabled", `{"expected_version":null,"enabled":"yes","percentage":10}`, "InvalidRequest"},
		{"missing percentage", `{"expected_version":null,"enabled":true}`, "InvalidRequest"},
		{"null percentage", `{"expected_version":null,"enabled":true,"percentage":null}`, "InvalidRequest"},
		{"float percentage", `{"expected_version":null,"enabled":true,"percentage":10.5}`, "InvalidRequest"},
		{"percentage over 100", `{"expected_version":null,"enabled":true,"percentage":101}`, "InvalidRequest"},
		{"percentage under 0", `{"expected_version":null,"enabled":true,"percentage":-1}`, "InvalidRequest"},
		{"unknown field", `{"expected_version":null,"enabled":true,"percentage":10,"extra":1}`, "InvalidRequest"},
		{"malformed json", `{"expected_version":null,`, "InvalidRequest"},
		{"empty body", ``, "InvalidRequest"},
