}

func TestConditionalConfigConcurrentSameExpected(t *testing.T) {
	h := newHarness(t)
	h.createEnv(t, "prod")
	h.createFlag(t, "checkout")
	first := h.conditional(t, `{"expected_version":null,"enabled":true,"percentage":10}`)
